Convert this TypeScript class to JavaScript:

class Session {
  private readonly token: string;
  private expires: number;

  constructor(token: string, ttl: number) {
    this.token = token;
    this.expires = Date.now() + ttl;
  }

  isValid(): boolean {
    return Date.now() < this.expires;
  }
}

