Convert this TypeScript typed event emitter to JavaScript:

interface Events {
  message: { text: string };
}

class Emitter<T extends Record<string, unknown>> {
  private handlers: { [K in keyof T]?: ((payload: T[K]) => void)[] } = {};
  on<K extends keyof T>(event: K, fn: (payload: T[K]) => void) {
    (this.handlers[event] ||= []).push(fn);
  }
}

